"use client";

import { useState, useEffect } from "react";
import NavBar from "@/components/NavBar";
import OrderForm from "@/components/OrderForm";
import ProductCard from "@/components/ProductCard";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";

interface Order {
  id: string;
  vendorName: string;
  rawMaterial: string;
  quantity: number;
  unit: string;
  price: number;
  address: string;
  status: string;
  orderDate: string;
  deliveryDate: string;
  comments?: string;
}

const featuredProducts = [
  {
    name: "Premium Basmati Rice",
    description: "Long grain, aromatic rice perfect for biryanis and pulavs. Aged for superior taste and texture.",
    price: "₹85",
    quality: "Grade A Premium",
    unit: "kg",
    inStock: true
  },
  {
    name: "Fresh Vegetables Mix",
    description: "Daily fresh mixed vegetables including onions, tomatoes, potatoes, and seasonal greens.",
    price: "₹45",
    quality: "Farm Fresh",
    unit: "kg",
    inStock: true
  },
  {
    name: "Refined Oil",
    description: "Pure refined sunflower oil, ideal for deep frying and cooking. Heart-healthy and light.",
    price: "₹120",
    quality: "Pure & Filtered",
    unit: "L",
    inStock: true
  },
  {
    name: "Spices Combo",
    description: "Authentic blend of essential spices including turmeric, red chili, coriander, and garam masala.",
    price: "₹200",
    quality: "Authentic Blend",
    unit: "kg",
    inStock: false
  }
];

export default function DashboardPage() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchOrders = async () => {
    try {
      const response = await fetch("/api/orders");
      const result = await response.json();
      
      if (result.success) {
        setOrders(result.orders);
      } else {
        toast.error("Failed to fetch orders");
      }
    } catch (error) {
      console.error("Error fetching orders:", error);
      toast.error("Network error while fetching orders");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const handleOrderSuccess = () => {
    fetchOrders(); // Refresh orders after successful submission
  };

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case "delivered":
        return "default";
      case "in transit":
        return "secondary";
      case "processing":
        return "outline";
      default:
        return "outline";
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <NavBar />
      
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-foreground mb-2">Vendor Dashboard</h1>
          <p className="text-muted-foreground">
            Manage your raw material orders and explore available products
          </p>
        </div>

        <Tabs defaultValue="order" className="space-y-6">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="order">Place Order</TabsTrigger>
            <TabsTrigger value="history">Order History</TabsTrigger>
            <TabsTrigger value="products">Browse Products</TabsTrigger>
          </TabsList>

          {/* Place Order Tab */}
          <TabsContent value="order" className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div>
                <OrderForm onOrderSuccess={handleOrderSuccess} />
              </div>
              <div className="space-y-6">
                <Card>
                  <CardHeader>
                    <CardTitle>Quick Stats</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="flex justify-between items-center">
                      <span className="text-muted-foreground">Total Orders</span>
                      <span className="font-semibold">{orders.length}</span>
                    </div>
                    <Separator />
                    <div className="flex justify-between items-center">
                      <span className="text-muted-foreground">Pending Orders</span>
                      <span className="font-semibold">
                        {orders.filter(order => order.status !== "Delivered").length}
                      </span>
                    </div>
                    <Separator />
                    <div className="flex justify-between items-center">
                      <span className="text-muted-foreground">Total Spent</span>
                      <span className="font-semibold">
                        ₹{orders.reduce((sum, order) => sum + order.price, 0).toLocaleString()}
                      </span>
                    </div>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle>Recent Activity</CardTitle>
                  </CardHeader>
                  <CardContent>
                    {orders.slice(0, 3).map((order) => (
                      <div key={order.id} className="flex justify-between items-center py-2">
                        <div>
                          <p className="font-medium text-sm">{order.rawMaterial}</p>
                          <p className="text-xs text-muted-foreground">{order.orderDate}</p>
                        </div>
                        <Badge variant={getStatusColor(order.status)}>
                          {order.status}
                        </Badge>
                      </div>
                    ))}
                  </CardContent>
                </Card>
              </div>
            </div>
          </TabsContent>

          {/* Order History Tab */}
          <TabsContent value="history" className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Order History</CardTitle>
                <CardDescription>
                  View all your previous and current orders
                </CardDescription>
              </CardHeader>
              <CardContent>
                {isLoading ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">Loading orders...</p>
                  </div>
                ) : orders.length === 0 ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">No orders found. Place your first order!</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {orders.map((order) => (
                      <Card key={order.id}>
                        <CardContent className="pt-6">
                          <div className="flex justify-between items-start mb-4">
                            <div>
                              <h3 className="font-semibold">{order.rawMaterial}</h3>
                              <p className="text-sm text-muted-foreground">Order ID: {order.id}</p>
                            </div>
                            <Badge variant={getStatusColor(order.status)}>
                              {order.status}
                            </Badge>
                          </div>
                          
                          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                            <div>
                              <p className="text-muted-foreground">Quantity</p>
                              <p className="font-medium">{order.quantity} {order.unit}</p>
                            </div>
                            <div>
                              <p className="text-muted-foreground">Total Price</p>
                              <p className="font-medium">₹{order.price.toLocaleString()}</p>
                            </div>
                            <div>
                              <p className="text-muted-foreground">Order Date</p>
                              <p className="font-medium">{order.orderDate}</p>
                            </div>
                            <div>
                              <p className="text-muted-foreground">Delivery Date</p>
                              <p className="font-medium">{order.deliveryDate}</p>
                            </div>
                          </div>
                          
                          <div className="mt-4">
                            <p className="text-muted-foreground text-sm">Delivery Address</p>
                            <p className="text-sm">{order.address}</p>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Browse Products Tab */}
          <TabsContent value="products" className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Available Products</CardTitle>
                <CardDescription>
                  Browse our selection of quality raw materials
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {featuredProducts.map((product, index) => (
                    <ProductCard
                      key={index}
                      name={product.name}
                      description={product.description}
                      price={product.price}
                      quality={product.quality}
                      unit={product.unit}
                      inStock={product.inStock}
                      onOrderClick={() => {
                        // Switch to order tab and pre-fill the form
                        const orderTab = document.querySelector('[value="order"]') as HTMLElement;
                        orderTab?.click();
                        toast.info(`${product.name} selected for ordering`);
                      }}
                    />
                  ))}
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}
